mapper.select:
SELECT t.id, t.product_part_code, t1.product_part_sign, t.update_time, t.create_time, t.delete_flag FROM ${stockTableName} t LEFT JOIN ${productPartTableName} t1 ON t.product_part_code = t1.primary_key WHERE t.delete_flag = false AND t.state = true AND t.stock_init_state = true AND t.enterprise_code = #{enterpriseCode}
AND t1.product_part_sign LIKE '%'|| #{productPartName} ||'%'
AND t.product_part_code NOT IN
#{excludeCode}
ORDER BY t.create_time DESC, t.id DESC

mapper.update:
UPDATE ${tableName}
SET shipping_space = #{shippingSpace}
WHERE delete_flag = false
  AND primary_key = #{stockCode}
  AND enterprise_code = #{enterpriseCode}

update ${tableName}
SET total_inventory = #{totalInventory},

    lock_in_inventor = #{lockInventory},

unqualified_inventory = #{unqualifiedInventory},
shipping_space = #{positionCodeArray,jdbcType=ARRAY,typeHandler=com.futurecraftsmen.pms.service.domain.ArrayTypeHandler}
where primary_key = #{stock}
and enterprise_code = #{enterpriseCode}

update ${tableName}
SET picture = #{pictures,jdbcType=ARRAY,typeHandler=com.futurecraftsmen.pms.service.domain.ArrayTypeHandler}
where primary_key = #{primaryKeyValue}
  and enterprise_code = #{enterpriseCode}


update ${tableName}
SET lock_In_Inventor=lock_In_Inventor + #{num}
  , update_time=now()
where primary_key = #{id}  and  lock_In_Inventor + #{num}<=total_inventory and state = true and stock_init_state = true

UPDATE ${tableName}

    safe_inventory = #{model.safeInventory},
    remark = #{model.remark},
    count_cycle = #{model.countCycle},
    state = #{model.state},
    bar_code_number = #{model.barCodeNumber},
    stock_limit = #{model.stockLimit},
    picture = #{model.picture}

where
enterprise_code = #{enterpriseCode}
and primary_key = #{model.stockCode}

